        'ಉಸಿರು ಬಿಟ್ಟು ಇನ್ನೊಂದು ಕಾಲನ್ನೂ ಮುಂದಕ್ಕೆ ತಂದು ಕಾಲುಗಳ ಮೇಲೆ ಬಾಗಿ.',
        'ಉಸಿರೆಳೆದು ಮೇಲಕ್ಕೆ ಏಳಿ, ತೋಳುಗಳನ್ನು ತಲೆಯ ಮೇಲಕ್ಕೆ ಚಾಚಿ.',
        'ಉಸಿರು ಬಿಟ್ಟು ಕೈಗಳನ್ನು ಎದೆಯ ಮುಂದೆ ತನ್ನಿ. ಅದು ಒಂದು ಸುತ್ತು.',
