        'ಭುಜಗಳನ್ನು ಒಳಕ್ಕೆ ಉರುಳಿಸಿ, ಆರಾಮವಾಗಿದ್ದರೆ ಕೆಳಗೆ ಕೈಗಳನ್ನು ಬೆಸೆಯಿರಿ.',
        'ಐದು ಉಸಿರುಗಳವರೆಗೆ ಹಿಡಿಯಿರಿ, ನಂತರ ಒಂದೊಂದೇ ಮಣಿಯಂತೆ ಇಳಿಸಿ.',
